  2114  /* Year, Month, Day Getters {{{1 */
  2115  /**
  2116   * g_date_time_get_ymd:
  2117   * @datetime: a #GDateTime.
  2118   * @year: (out) (optional): the return location for the gregorian year, or %NULL.
  2119   * @month: (out) (optional): the return location for the month of the year, or %NULL.
  2120   * @day: (out) (optional): the return location for the day of the month, or %NULL.
  2121   *
  2122   * Retrieves the Gregorian day, month, and year of a given #GDateTime.
  2123   *
  2124   * Since: 2.26
  2125   **/
  2126  void
  2127  g_date_time_get_ymd (GDateTime *datetime,
  2128                       gint      *year,
  2129                       gint      *month,
  2130                       gint      *day)
  2131  {
  2132    gint the_year;
  2133    gint the_month;
  2134    gint the_day;
  2135    gint remaining_days;
  2136    gint y100_cycles;
  2137    gint y4_cycles;
  2138    gint y1_cycles;
  2139    gint preceding;
  2140    gboolean leap;
  2141
  2142    g_return_if_fail (datetime != NULL);
  2143
  2144    remaining_days = datetime->days;
  2145
  2146    /*
  2147     * We need to convert an offset in days to its year/month/day representation.
  2148     * Leap years makes this a little trickier than it should be, so we use
  2149     * 400, 100 and 4 years cycles here to get to the correct year.
  2150     */
  2151
  2152    /* Our days offset starts sets 0001-01-01 as day 1, if it was day 0 our
  2153     * math would be simpler, so let's do it */
  2154    remaining_days--;
  2155
  2156    the_year = (remaining_days / DAYS_IN_400YEARS) * 400 + 1;
  2157    remaining_days = remaining_days % DAYS_IN_400YEARS;
  2158
  2159    y100_cycles = remaining_days / DAYS_IN_100YEARS;
  2160    remaining_days = remaining_days % DAYS_IN_100YEARS;
  2161    the_year += y100_cycles * 100;
  2162
  2163    y4_cycles = remaining_days / DAYS_IN_4YEARS;
  2164    remaining_days = remaining_days % DAYS_IN_4YEARS;
  2165    the_year += y4_cycles * 4;
  2166
  2167    y1_cycles = remaining_days / 365;
  2168    the_year += y1_cycles;
  2169    remaining_days = remaining_days % 365;
  2170
  2171    if (y1_cycles == 4 || y100_cycles == 4) {
  2172      g_assert (remaining_days == 0);
  2173
  2174      /* special case that indicates that the date is actually one year before,
  2175       * in the 31th of December */
  2176      the_year--;
  2177      the_month = 12;
  2178      the_day = 31;
  2179      goto end;
  2180    }
  2181
  2182    /* now get the month and the day */
  2183    leap = y1_cycles == 3 && (y4_cycles != 24 || y100_cycles == 3);
  2184
  2185    g_assert (leap == GREGORIAN_LEAP(the_year));
  2186
  2187    the_month = (remaining_days + 50) >> 5;
  2188    preceding = (days_in_year[0][the_month - 1] + (the_month > 2 && leap));
  2189    if (preceding > remaining_days)
  2190      {
  2191        /* estimate is too large */
  2192        the_month -= 1;
  2193        preceding -= leap ? days_in_months[1][the_month]
  2194                          : days_in_months[0][the_month];
  2195      }
  2196
  2197    remaining_days -= preceding;
  2198    g_assert(0 <= remaining_days);
  2199
  2200    the_day = remaining_days + 1;
  2201
  2202  end:
  2203    if (year)
  2204      *year = the_year;
  2205    if (month)
  2206      *month = the_month;
  2207    if (day)
  2208      *day = the_day;
  2209  }
