  2211  /**
  2212   * g_date_time_get_year:
  2213   * @datetime: A #GDateTime
  2214   *
  2215   * Retrieves the year represented by @datetime in the Gregorian calendar.
  2216   *
  2217   * Returns: the year represented by @datetime
  2218   *
  2219   * Since: 2.26
  2220   */
  2221  gint
  2222  g_date_time_get_year (GDateTime *datetime)
  2223  {
  2224    gint year;
  2225
  2226    g_return_val_if_fail (datetime != NULL, 0);
  2227
  2228    g_date_time_get_ymd (datetime, &year, NULL, NULL);
  2229
  2230    return year;
  2231  }
