  2257   * g_date_time_get_day_of_month:
  2258   * @datetime: a #GDateTime
  2259   *
  2260   * Retrieves the day of the month represented by @datetime in the gregorian
  2261   * calendar.
  2262   *
  2263   * Returns: the day of the month
  2264   *
  2265   * Since: 2.26
  2266   */
  2267  gint
  2268  g_date_time_get_day_of_month (GDateTime *datetime)
  2269  {
  2270    gint           day_of_year,
  2271                   i;
  2272    const guint16 *days;
  2273    guint16        last = 0;
  2274
  2275    g_return_val_if_fail (datetime != NULL, 0);
  2276
  2277    days = days_in_year[GREGORIAN_LEAP (g_date_time_get_year (datetime)) ? 1 : 0];
  2278    g_date_time_get_week_number (datetime, NULL, NULL, &day_of_year);
  2279
  2280    for (i = 1; i <= 12; i++)
  2281      {
  2282        if (days [i] >= day_of_year)
  2283          return day_of_year - last;
  2284        last = days [i];
  2285      }
  3460  }
